import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import './App.css';

// Components
import LoginScreen from './components/LoginScreen';
import ChatInterface from './components/ChatInterface';
import LoadingScreen from './components/LoadingScreen';

// Services
import { authService } from './services/authService';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    console.log('[App] Checking for existing token...');
    // Check if user is already logged in
    const token = localStorage.getItem('access_token');
    if (token) {
      console.log('[App] Token found, verifying...');
      authService.verifyToken(token)
        .then(userData => {
          console.log('[App] Token verified, user data:', userData);
          setUser(userData);
          setIsAuthenticated(true);
          initializeSocket(token);
        })
        .catch((error) => {
          console.log('[App] Token verification failed:', error);
          localStorage.removeItem('access_token');
          setIsLoading(false);
        });
    } else {
      console.log('[App] No token found');
      setIsLoading(false);
    }
  }, []);

  const initializeSocket = (token) => {
    console.log('[App] Initializing socket connection...');
    const newSocket = io('http://localhost:5000');

    newSocket.on('connect', () => {
      console.log('[Socket] Connected to server');
      // Authenticate with the server using the token
      newSocket.emit('authenticate', { token: token });
    });

    newSocket.on('connected', (data) => {
      console.log('[Socket] Server welcome:', data.message);
    });

    newSocket.on('authenticated', (data) => {
      console.log('[Socket] Authentication successful:', data.message);
    });

    newSocket.on('auth_error', (data) => {
      console.error('[Socket] Authentication error:', data.message);
      localStorage.removeItem('access_token');
      setIsAuthenticated(false);
      setUser(null);
    });

    newSocket.on('error', (data) => {
      console.error('[Socket] Error:', data.message);
    });

    setSocket(newSocket);
    setIsLoading(false);
    console.log('[App] Socket initialized, loading complete');
  };

  const handleLogin = async (credentials) => {
    try {
      console.log('[App] Login attempt for:', credentials.username);
      setIsLoading(true);
      const response = await authService.login(credentials);

      console.log('[App] Login successful, response:', response);
      localStorage.setItem('access_token', response.access_token);
      setUser(response.user);
      setIsAuthenticated(true);

      console.log('[App] State updated - isAuthenticated:', true, 'user:', response.user);
      initializeSocket(response.access_token);
    } catch (error) {
      console.error('[App] Login failed:', error);
      setIsLoading(false);
      throw error;
    }
  };

  const handleRegister = async (userData) => {
    try {
      console.log('[App] Register attempt for:', userData.username);
      setIsLoading(true);
      const response = await authService.register(userData);

      console.log('[App] Registration successful, response:', response);
      localStorage.setItem('access_token', response.access_token);
      setUser(response.user);
      setIsAuthenticated(true);

      console.log('[App] State updated - isAuthenticated:', true, 'user:', response.user);
      initializeSocket(response.access_token);
    } catch (error) {
      console.error('[App] Registration failed:', error);
      setIsLoading(false);
      throw error;
    }
  };

  const handleLogout = () => {
    console.log('[App] Logging out...');
    if (socket) {
      socket.disconnect();
    }
    localStorage.removeItem('access_token');
    setUser(null);
    setIsAuthenticated(false);
    setSocket(null);
  };

  console.log('[App] Render - isLoading:', isLoading, 'isAuthenticated:', isAuthenticated, 'user:', user);

  if (isLoading) {
    console.log('[App] Rendering LoadingScreen');
    return <LoadingScreen />;
  }

  if (!isAuthenticated) {
    console.log('[App] Rendering LoginScreen');
    return (
      <LoginScreen
        onLogin={handleLogin}
        onRegister={handleRegister}
        isLoading={isLoading}
      />
    );
  }

  console.log('[App] Rendering ChatInterface');
  return (
    <div className="App">
      <ChatInterface
        user={user}
        socket={socket}
        onLogout={handleLogout}
      />
    </div>
  );
}

export default App;
